import React, { useState, useEffect } from 'react';
import { 
  Container, 
  Typography, 
  Grid, 
  Card, 
  CardContent, 
  Button, 
  Box
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const StudentDashboard = () => {
  const [stats, setStats] = useState({ applications: 0 });
  const navigate = useNavigate();

  useEffect(() => {
    fetchStudentStats();
  }, []);

  const fetchStudentStats = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/students/applications');
      setStats({ applications: response.data.applications.length });
    } catch (error) {
      console.error('Error fetching student stats:', error);
    }
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Student Dashboard
      </Typography>
      
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} md={4}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                My Applications
              </Typography>
              <Typography variant="h4">
                {stats.applications}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Card sx={{ cursor: 'pointer' }} onClick={() => navigate('/institutions')}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                🎓 Browse Institutions
              </Typography>
              <Typography color="textSecondary">
                Discover higher learning institutions and their courses. Apply for up to 2 courses per institution.
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12} md={6}>
          <Card sx={{ cursor: 'pointer' }} onClick={() => navigate('/jobs')}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                💼 Find Jobs
              </Typography>
              <Typography color="textSecondary">
                Explore career opportunities from partner companies. Upload your transcripts to get matched.
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={6}>
          <Card sx={{ cursor: 'pointer' }} onClick={() => navigate('/applications')}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                📋 My Applications
              </Typography>
              <Typography color="textSecondary">
                Track your course applications and admission status.
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={6}>
          <Card sx={{ cursor: 'pointer' }} onClick={() => navigate('/profile')}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                👤 My Profile
              </Typography>
              <Typography color="textSecondary">
                Update your personal information and upload academic transcripts.
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Container>
  );
};

export default StudentDashboard;
